import unittest
import boto3
from moto import mock_s3

@mock_s3
class BaseTest(unittest.TestCase):
    def setUp(self):
        self.s3 = boto3.resource('s3', region_name='us-east-1')
        self.test_bucket = self.s3.Bucket("testbucket")
        self.test_bucket.create()
    def tearDown(self):
        self.test_bucket.delete()

@mock_s3
class MyTest(BaseTest):
    def test_a_thing(self):
        # bucket should exist during test
        self.s3.meta.client.head_bucket(Bucket="testbucket")

# plain case: no setUp at all -> still resets between tests
@mock_s3
class PlainTest(unittest.TestCase):
    def test_one(self):
        boto3.client('s3', region_name='us-east-1').create_bucket(Bucket='b1')
    def test_two(self):
        # b1 should have been reset
        buckets = boto3.client('s3', region_name='us-east-1').list_buckets()['Buckets']
        assert buckets == [], buckets

suite = unittest.TestSuite()
for cls, name in [(MyTest, 'test_a_thing'), (PlainTest, 'test_one'), (PlainTest, 'test_two')]:
    suite.addTest(cls(name))
r = unittest.TextTestRunner(verbosity=2).run(suite)
assert r.wasSuccessful()
